B.an7=s(["\u555f\u52d5\u54c1\u724c\u9801\u6539\u70ba\u4f9d\u88dd\u7f6e\u6bd4\u4f8b\u9078\u64c7\u7684\u5b8c\u6574\u55ae\u5f35\u5716\u7247\uff0c\u4e0d\u518d\u5206\u5225\u8f09\u5165\u5c0f\u8c93\u8207 logo\u3002","\u884c\u7a0b\u898f\u5283\u8207\u5de5\u4f5c\u8ffd\u8e64\u6458\u8981\u8cc7\u8a0a\u5361\u65b0\u589e\u5c0e\u89bd\u7bad\u982d\uff0c\u53ef\u76f4\u63a5\u524d\u5f80\u5c0d\u61c9\u6e05\u55ae\u3002","\u56db\u500b\u4e3b\u8981\u9801\u9762\u52a0\u5165\u5404\u81ea\u7368\u7acb\u7684\u9996\u6b21\u63a2\u7167\u71c8\u5c0e\u89bd\uff0c\u7531\u81ea\u8a02\u540d\u7a31\u7684\u5c0f\u55b5\u624b\u9010\u6b65\u4ecb\u7d39\u529f\u80fd\u3002","\u6bcf\u4f4d\u6703\u54e1\u5728\u6bcf\u53f0\u88dd\u7f6e\u7684\u5c0e\u89bd\u9032\u5ea6\u6703\u7368\u7acb\u4fdd\u5b58\uff0c\u770b\u904e\u5f8c\u4e0d\u6703\u53cd\u8986\u51fa\u73fe\u3002","\u6d6a\u55b5\u8207\u5c0f\u55b5\u624b\u4e92\u76f8\u81ea\u6211\u4ecb\u7d39\u6642\uff0c\u6703\u6b63\u78ba\u4f7f\u7528\u6703\u54e1\u8a2d\u5b9a\u7684\u5c0f\u55b5\u624b\u540d\u7a31\u3002","\u8a18\u5e33\u7ba1\u7406\u7684\u74b0\u5f62\u5716\u6539\u7528\u65b0\u8c93\u54aa\u5716\u6848\uff0c\u74b0\u5e36\u6703\u4f9d\u6536\u5165\u8207\u652f\u51fa\u6bd4\u4f8b\u52d5\u614b\u8b8a\u8272\u3002"],t.s)
B.ad0=s(["The startup brand page now uses one flattened image per device orientation instead of loading separate cat and logo assets.","Schedule and Work Tracking summary cards now include arrows that navigate directly to their related lists.","Each of the four main pages has an independent first-use spotlight tour led by the custom-named assistant.","Tour completion is stored separately for each member and device, so completed guidance does not repeat.","Stray Cat introductions now use the assistant name selected by the member.","The ledger donut mode now uses the new cat artwork, with an animated ring colored by income and expense proportions."],t.s)
B.Wl=new A.cx("v1.2.132+140","\u8cc7\u8a0a\u5361\u5c0e\u89bd\u3001\u65b0\u624b\u6559\u5b78\u3001\u52d5\u614b\u8c93\u54aa\u5716\u8868\u8207\u55ae\u5716\u555f\u52d5\u756b\u9762","Navigation, onboarding, cat charts, and a single-image startup screen",B.an7,B.ad0)
B.aoe=s(["Logo \u555f\u52d5\u756b\u9762\u8abf\u6574\u70ba\u7d04\u4e94\u79d2\uff0c\u9ede\u64ca\u6216\u89f8\u78b0\u756b\u9762\u53ef\u76f4\u63a5\u9032\u5165\u7248\u672c\u78ba\u8a8d\u968e\u6bb5\u3002","Android \u6b63\u5f0f\u7248\u6539\u7528\u542b Supabase \u516c\u958b\u9023\u7dda\u53c3\u6578\u7684\u5c08\u7528\u5efa\u7f6e\u6d41\u7a0b\uff0c\u4fee\u6b63\u767b\u5165\u5f8c\u9032\u5165\u793a\u7bc4\u6a21\u5f0f\u3002","Android \u884c\u7a0b\u63d0\u9192\u6539\u7528\u65b0\u7684\u6e05\u695a\u8c93\u53eb\u8072\u3002"],t.s)
B.anC=s(["The Logo startup screen now stays for about five seconds and can be skipped by tapping or clicking it.","Android production builds now use the dedicated Supabase-enabled build flow, fixing the demo-mode fallback after sign-in.","Android reminders now use the new, clearer cat sound."],t.s)
